use codeint_model::language::SourceSet;

#[cfg(test)]
mod tests;

const GENERATED_SUFFIXES: [&str; 8] = [
    ".g.dart",
    ".freezed.dart",
    ".gr.dart",
    ".mocks.dart",
    ".pb.dart",
    ".pbenum.dart",
    ".pbjson.dart",
    ".pbserver.dart",
];

const GENERATED_MARKERS: [&str; 6] = [
    "generated code",
    "@generated",
    "do not edit",
    "do not modify by hand",
    "auto-generated",
    "autogenerated",
];

pub(crate) fn classify(path: &str, header_comments: &str) -> SourceSet {
    if is_generated(path, header_comments) {
        return SourceSet::Generated;
    }
    if is_test_path(path) {
        return SourceSet::Test;
    }
    SourceSet::Production
}

fn is_generated(path: &str, header_comments: &str) -> bool {
    if GENERATED_SUFFIXES
        .iter()
        .any(|suffix| path.ends_with(suffix))
    {
        return true;
    }
    let lower = header_comments.to_ascii_lowercase();
    GENERATED_MARKERS
        .iter()
        .any(|marker| lower.contains(marker))
}

fn is_test_path(path: &str) -> bool {
    if path.ends_with("_test.dart") {
        return true;
    }
    let Some((parent, _)) = path.rsplit_once('/') else {
        return false;
    };
    parent
        .split('/')
        .any(|segment| matches!(segment, "test" | "tests" | "integration_test"))
}
